# 41_figure.R: decisive-validation multipanel figure (plotting only). Run from final/.
# A niches and guild dominance; B independent Monte Carlo truth; C additive-model predictions; D cross-predictor interaction predictions (weak shrinkage 1e-6); E predictive gains and conditional-contrast recovery across orders; F identifiability and null recovery.
suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(tidyr); library(patchwork); library(scales)}); stopifnot(requireNamespace("svglite", quietly = TRUE)); IN <- "revision_ident/tables"; OUTF <- "revision_ident/figures"
ink <- "#252B2D"; petrol <- "#246878"; orange <- "#C45C19"; sage <- "#79936C"; purple <- "#615A83"; grey <- "#848B8D"; grid_col <- "#E5E9E9"
base <- theme_minimal(base_size = 8.5, base_family = "sans") + theme(text = element_text(colour = ink), axis.text = element_text(size = 6.6, colour = ink), axis.title = element_text(size = 7.4, colour = ink), axis.line = element_line(colour = ink, linewidth = .3), axis.ticks = element_line(colour = ink, linewidth = .25), axis.ticks.length = unit(1, "mm"), panel.grid.major = element_line(colour = grid_col, linewidth = .25), panel.grid.minor = element_blank(), panel.spacing = unit(2, "mm"), strip.background = element_blank(),
  strip.text = element_text(size = 6.8, face = "bold", colour = ink), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 6.6), legend.key.height = unit(2.4, "mm"), legend.key.width = unit(5, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(1, "mm"), plot.tag = element_text(size = 11, face = "bold"), plot.margin = margin(2, 3, 1, 2))
SC <- c(constant = "Constant", increasing = "Increasing", reversed = "Reversed")
# ---- A
nic <- read.csv(file.path(IN, "meta_niche_curves.csv")); dom <- read.csv(file.path(IN, "meta_guild_dominance.csv"))
pA1 <- ggplot(nic, aes(X, niche, group = species, colour = guild)) + geom_line(linewidth = .2, alpha = .35) + scale_colour_manual(values = c(specialist = petrol, generalist = orange)) + scale_y_continuous(limits = c(0, NA), oob = squish) + coord_cartesian(ylim = c(0, .06)) + labs(tag = "A", x = "pH gradient", y = "Species response") + base + guides(colour = guide_legend(override.aes = list(linewidth = .8, alpha = 1)))
pA2 <- ggplot(dom, aes(P, generalist_dominance, colour = scenario, linetype = scenario)) + geom_line(linewidth = .8) + scale_colour_manual(values = c(constant = grey, increasing = purple, reversed = sage), labels = SC) + scale_linetype_manual(values = c(constant = "42", increasing = "solid", reversed = "solid"), labels = SC) + scale_y_continuous(limits = c(0, 1)) + labs(x = "Productivity gradient", y = "Generalist share") + base
# ---- B-D: relative-abundance dissimilarity vs productivity at two pH spreads (pH position 0.5), k = 2
S <- read.csv(file.path(IN, "meta_surfaces.csv")) |> filter(order == 2, abs(m - .5) < 1e-9, abs(h - .1) < 1e-9 | abs(h - .3) < 1e-9)
agg <- S |> group_by(scenario, config, h, Pm) |> summarise(est = mean(resp_est), est_lo = quantile(resp_est, .025), est_hi = quantile(resp_est, .975), truth = mean(resp_true), .groups = "drop") |> mutate(scenario = factor(scenario, names(SC), SC), hl = factor(ifelse(abs(h - .1) < 1e-9, "pH spread 0.1", "pH spread 0.3"), c("pH spread 0.1", "pH spread 0.3"))); write.csv(agg, file.path(OUTF, "Figure_decisive_BCD_plotted.csv"), row.names = FALSE)
hcol <- c("pH spread 0.1" = petrol, "pH spread 0.3" = orange)
pB <- ggplot(agg |> filter(config == "additive"), aes(Pm, truth, colour = hl)) + geom_line(linewidth = .8) + geom_point(size = 1.2) + facet_wrap(~scenario, nrow = 1) + scale_colour_manual(values = hcol) + scale_y_continuous(limits = c(0, 1)) + labs(tag = "B", x = NULL, y = "Truth (Monte Carlo)") + base + theme(axis.text.x = element_blank())
mk <- function(cfg, tag) ggplot(agg |> filter(config == cfg), aes(Pm, est, colour = hl)) + geom_linerange(aes(ymin = est_lo, ymax = est_hi), linewidth = .35, alpha = .5) + geom_line(linewidth = .8) + geom_point(size = 1.2) + geom_line(aes(y = truth), linetype = "dotted", linewidth = .5, colour = ink) + facet_wrap(~scenario, nrow = 1) + scale_colour_manual(values = hcol) + scale_y_continuous(limits = c(0, 1)) + labs(tag = tag, x = if (tag == "D") "Productivity (mean of set)" else NULL, y = if (tag == "C") "Additive prediction" else "Cross-predictor prediction") + base + theme(strip.text = element_blank(), axis.text.x = if (tag == "D") element_text() else element_blank())
pC <- mk("additive", "C"); pD <- mk("cross_1e-06", "D")
# ---- E
G <- read.csv(file.path(IN, "meta_summary_gains.csv")) |> filter(response == "relative", arm == "balanced", contrast %in% c("cross_1e-06 minus additive", "same_1e-06 minus additive")) |> mutate(model = ifelse(grepl("^cross", contrast), "Cross-predictor", "Same-predictor"), scenario = factor(scenario, names(SC), SC)); write.csv(G, file.path(OUTF, "Figure_decisive_E_gains.csv"), row.names = FALSE)
pE1 <- ggplot(G, aes(order, median, colour = model)) + geom_hline(yintercept = 0, colour = "#A2AAAC", linewidth = .3) + geom_linerange(aes(ymin = q025, ymax = q975), position = position_dodge(.5), linewidth = .35, alpha = .55) + geom_line(linewidth = .6, position = position_dodge(.5)) + geom_point(size = 1.1, position = position_dodge(.5)) + facet_wrap(~scenario, nrow = 1, scales = "free_y") + scale_colour_manual(values = c("Cross-predictor" = orange, "Same-predictor" = purple)) + scale_x_continuous(breaks = c(2, 3, 4, 5, 8)) + labs(tag = "E", x = NULL, y = expression(Delta * D^2 * " vs additive")) + base + theme(axis.text.x = element_blank())
Ct <- read.csv(file.path(IN, "meta_summary_contrasts.csv")) |> filter(contrast == "link_did_P", response == "relative", arm == "balanced", config %in% c("additive", "same_1e-06", "cross_1e-06"), scenario != "constant") |> mutate(model = factor(config, c("additive", "same_1e-06", "cross_1e-06"), c("Additive", "Same-predictor", "Cross-predictor")), scenario = factor(scenario, names(SC), SC)); tr <- Ct |> filter(config == "additive")
pE2 <- ggplot(Ct, aes(order, est_median, colour = model)) + geom_hline(data = tr, aes(yintercept = 0), colour = "#A2AAAC", linewidth = .3) + geom_line(data = tr, aes(y = true), colour = ink, linetype = "dotted", linewidth = .6) + geom_linerange(aes(ymin = est_q025, ymax = est_q975), position = position_dodge(.5), linewidth = .35, alpha = .55) + geom_line(linewidth = .6, position = position_dodge(.5)) + geom_point(size = 1.1, position = position_dodge(.5)) + facet_wrap(~scenario, nrow = 1, scales = "free_y") + scale_colour_manual(values = c(Additive = grey, "Same-predictor" = purple, "Cross-predictor" = orange)) + scale_x_continuous(breaks = c(2, 3, 4, 5, 8)) + labs(x = "Zeta order, k", y = "pH-spread effect: high - low P (link)") + base + theme(strip.text = element_blank())
# ---- F
Rk <- read.csv(file.path(IN, "identifiability_A_rank_summary.csv")) |> filter(layout == "package_all_predictors") |> mutate(source = factor(source, c("random2", "balanced2", "epa"), c("Random sets", "Balanced design", "EPA lakes")))
pF1 <- ggplot(Rk, aes(order, 100 * interaction_info_fraction_mean, colour = source)) + geom_line(linewidth = .6) + geom_point(aes(shape = rank_full < n_parameters_full), size = 1.5) + scale_shape_manual(values = c(`FALSE` = 16, `TRUE` = 4), labels = c(`FALSE` = "full rank", `TRUE` = "rank-deficient")) + scale_colour_manual(values = c(petrol, orange, sage)) + scale_x_continuous(breaks = c(2, 3, 4, 5, 8)) + labs(tag = "F", x = "Zeta order, k", y = "Interaction variance outside\nthe additive design (%)") + base
Ib <- read.csv(file.path(IN, "balancedB_summary_interaction_recovery.csv")) |> filter(arm == "balanced", order %in% c(3, 5), stage %in% c("unpenalised", "ridge", "curvature", "shrink", "weakshrink", "selected"), scenario %in% c("none", "strong")) |> mutate(stage = factor(stage, c("unpenalised", "ridge", "curvature", "weakshrink", "shrink", "selected"), c("Unpenalised", "Ridge", "+ curvature", "+ shrink 1e-6", "+ shrink 5e-3", "Selected")), ordl = paste0("k = ", order), val = ifelse(scenario == "strong", est_explicit_link_did_median / true_explicit_link_did, est_explicit_link_did_median), what = ifelse(scenario == "strong", "Strong: estimate / truth", "Null: estimate (truth 0)"))
pF2 <- ggplot(Ib, aes(stage, val, fill = ordl)) + geom_col(position = position_dodge(.8), width = .7) + facet_wrap(~what, nrow = 1, scales = "free_y") + scale_fill_manual(values = c("k = 3" = petrol, "k = 5" = orange)) + labs(x = NULL, y = "Link-scale contrast") + base + theme(axis.text.x = element_text(angle = 35, hjust = 1, size = 6))
fig <- ((pA1 | pA2) / pB / pC / pD / (pE1 / pE2) / (pF1 | pF2)) + plot_layout(heights = c(.85, .7, .7, .75, 1.45, 1.0))
for (ext in c("pdf", "svg", "png")) ggsave(file.path(OUTF, paste0("Figure_decisive_interaction_validation.", ext)), fig, width = 183, height = 270, units = "mm", dpi = 600, bg = "white", device = switch(ext, pdf = grDevices::cairo_pdf, svg = svglite::svglite, png = "png"))
# Notes: B-D k = 2, pH position 0.5, relative-abundance dissimilarity vs set-mean productivity at two pH spreads (dotted black = truth in C, D; bars = central 95% interval over 50 replicates). E weak-shrinkage (1e-6) interactions, balanced site combinations, relative abundance. F1 package parameterisation; F2 known-parameter simulation (balanced configurations, 50 noisy replicates).
